typedef unsigned int size_t;

class stringx
{
  char *characters;
  void *buffer;
public:
  ~stringx();
};

template<class T>
class list
{
public:
  class iterator
  {
    void *node;
  public:
    T &operator*() const;
  };

  ~list();
  size_t size() const;
  iterator begin();
  void erase(iterator);
};

class wevent;
class widget;

typedef list<widget *> widget_list_t;
typedef list<wevent *> wevent_list_t;

class widget
{
public:
  virtual ~widget();
  virtual void flush();

protected:
  stringx widget_name;
  int type;
  widget *parent;
  widget_list_t children;
  unsigned int flags;
  wevent_list_t wevent_run_list;
};

widget::~widget()
{
  flush();

  // delete children
  while ( children.size() )
  {
    delete *children.begin();
    children.erase( children.begin() );
  }
}
